import { useState } from "react";

interface UseControlledOpenProps {
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
}

interface UseControlledOpenResult {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  close: () => void;
}

export const useControlledOpen = ({
  open,
  onOpenChange,
}: UseControlledOpenProps): UseControlledOpenResult => {
  const [internalOpen, setInternalOpen] = useState(false);

  // Determine if the component is controlled or uncontrolled
  const isControlled = open !== undefined;
  const isOpen = isControlled ? open : internalOpen;

  const setIsOpen = (newOpen: boolean) => {
    if (!isControlled) {
      setInternalOpen(newOpen);
    }
    if (onOpenChange) {
      onOpenChange(newOpen);
    }
  };

  const close = () => setIsOpen(false);

  return { close, isOpen, setIsOpen };
};

"use client";

import { Drawer } from "@base-ui/react/drawer";
import React from "react";

import type { ReactFC } from "@/lib/types";
import { cn } from "@/lib/utils";
import { useControlledOpen } from "@/registry/hooks/useControlledOpen";
import { DrawerContext } from "@/registry/new-york/bottom-drawer/DrawerContext";

export interface BottomDrawerClassNames {
  overlay?: string | undefined;
  content?: string | undefined;
  handle?: string | undefined;
  title?: string | undefined;
  headerWrapper?: string | undefined;
  childrenWrapper?: string | undefined;
}

export interface BottomDrawerProps {
  title?: string | undefined;
  open?: boolean | undefined;
  onOpenChangeComplete?: ((open: boolean) => void) | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  trigger?: React.ReactNode | undefined;
  classNames?: BottomDrawerClassNames | undefined;
  renderHeader?:
    | ((props: {
        handle: React.ReactNode;
        close: () => void;
      }) => React.ReactNode)
    | null;
}

export const BottomDrawer: ReactFC<BottomDrawerProps> = ({
  children,
  title,
  open,
  onOpenChange,
  onOpenChangeComplete,
  trigger,
  classNames,
  renderHeader,
}) => {
  const { isOpen, setIsOpen, close } = useControlledOpen({
    onOpenChange,
    open,
  });

  const [viewportWidth, setViewportWidth] = React.useState<number>();
  React.useLayoutEffect(() => {
    if (!isOpen) {
      return;
    }
    // Scroll locking reserves a root scrollbar gutter, which also shrinks vw.
    // Both portal layers must cover the actual window, including that gutter.
    const updateWidth = () => setViewportWidth(window.innerWidth);
    updateWidth();
    window.addEventListener("resize", updateWidth);
    return () => window.removeEventListener("resize", updateWidth);
  }, [isOpen]);

  const contextValue = React.useMemo(() => ({ close }), [close]);

  const handle = (
    <div
      aria-hidden="true"
      className={cn(
        "mx-auto mb-4 h-1.5 w-12 shrink-0 rounded-full bg-zinc-300 dark:bg-zinc-700",
        classNames?.handle
      )}
    />
  );

  const defaultHeader = (
    <>
      {handle}
      <Drawer.Title
        className={cn(
          "mb-4 text-lg font-semibold text-zinc-900 dark:text-white",
          classNames?.title,
          !title && "sr-only"
        )}
      >
        {title || "Drawer"}
      </Drawer.Title>
      <Drawer.Description className="sr-only">
        {title ? `${title} drawer` : "Drawer content"}
      </Drawer.Description>
    </>
  );

  const noHeader = renderHeader === null;

  return (
    <DrawerContext.Provider value={contextValue}>
      <Drawer.Root
        open={isOpen}
        onOpenChange={setIsOpen}
        onOpenChangeComplete={onOpenChangeComplete}
        swipeDirection="down"
      >
        {trigger &&
          (React.isValidElement(trigger) ? (
            <Drawer.Trigger render={trigger} />
          ) : (
            <Drawer.Trigger>{trigger}</Drawer.Trigger>
          ))}

        <Drawer.Portal>
          <Drawer.Backdrop
            data-slot="bottom-drawer-backdrop"
            style={{ width: viewportWidth }}
            className={cn(
              "fixed inset-y-0 left-0 z-[9999] w-screen bg-black/40 opacity-[calc(1-var(--drawer-swipe-progress,0))] transition-opacity duration-300 data-ending-style:opacity-0 data-starting-style:opacity-0 data-swiping:duration-0 motion-reduce:transition-none dark:bg-black/60",
              classNames?.overlay
            )}
          />
          <Drawer.Viewport
            style={{ width: viewportWidth }}
            className="pointer-events-none fixed inset-y-0 left-0 z-[9999] flex w-screen items-end justify-center"
          >
            <Drawer.Popup
              data-slot="bottom-drawer-content"
              className={cn(
                "relative flex w-[95%] min-w-0 flex-col rounded-t-[10px] bg-white dark:bg-zinc-900",
                "dark:border-t dark:border-zinc-800",
                "pointer-events-auto max-h-[90dvh] max-w-[500px] transform-[translateY(var(--drawer-swipe-movement-y,0px))] transition-transform duration-300 ease-out outline-none data-ending-style:translate-y-full data-starting-style:translate-y-full data-swiping:duration-0 motion-reduce:transition-none",
                classNames?.content,
                {
                  "pt-6": !noHeader,
                }
              )}
            >
              {(noHeader || renderHeader) && (
                <>
                  <Drawer.Title className="sr-only">
                    {title || "Drawer"}
                  </Drawer.Title>
                  <Drawer.Description className="sr-only">
                    {title ? `${title} drawer` : "Drawer content"}
                  </Drawer.Description>
                </>
              )}
              {!noHeader && (
                <div
                  className={cn(
                    "shrink-0 rounded-t-[10px] bg-white px-4 text-left dark:bg-zinc-900",
                    classNames?.headerWrapper
                  )}
                >
                  {renderHeader
                    ? renderHeader({ close, handle })
                    : defaultHeader}
                </div>
              )}
              <Drawer.Content
                className={cn(
                  "min-h-0 flex-1 overflow-x-hidden overflow-y-auto overscroll-contain bg-white px-4 pt-0 pb-[max(1rem,env(safe-area-inset-bottom))] text-left dark:bg-zinc-900",
                  noHeader && "rounded-t-[10px] pt-6",
                  classNames?.childrenWrapper
                )}
              >
                {children}
              </Drawer.Content>
            </Drawer.Popup>
          </Drawer.Viewport>
        </Drawer.Portal>
      </Drawer.Root>
    </DrawerContext.Provider>
  );
};

"use client";

import React from "react";

import type { ReactFC } from "@/lib/types";
import { cn } from "@/lib/utils";
import { useControlledOpen } from "@/registry/hooks/useControlledOpen";
import type { BottomDrawerClassNames } from "@/registry/new-york/bottom-drawer/BottomDrawer";
import { BottomDrawer } from "@/registry/new-york/bottom-drawer/BottomDrawer";
import { BottomDrawerMenuItems } from "@/registry/new-york/bottom-drawer/BottomDrawerMenuComponents";
import type { BottomDrawerMenuItemProps } from "@/registry/new-york/bottom-drawer/BottomDrawerMenuItem";
import { BottomDrawerMenuItem } from "@/registry/new-york/bottom-drawer/BottomDrawerMenuItem";
import { MenuProvider } from "@/registry/new-york/menu-context/MenuContext";

export interface BottomDrawerMenuProps {
  children: React.ReactNode;
  content?: React.ReactNode | undefined;
  items?:
    | (Omit<BottomDrawerMenuItemProps, "children"> & { label: string })[]
    | undefined;
  title?: string | undefined;
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  closeOnClick?: boolean | undefined;
  classNames?: BottomDrawerClassNames | undefined;
}

export const BottomDrawerMenu: ReactFC<BottomDrawerMenuProps> = ({
  children,
  content,
  items,
  title,
  open,
  onOpenChange,
  closeOnClick = true,
  classNames,
}) => {
  const { isOpen, setIsOpen, close } = useControlledOpen({
    onOpenChange,
    open,
  });

  // Function to close the menu when clicking on menu items
  const closeMenu = () => {
    if (closeOnClick) {
      close();
    }
  };

  // Determine what to render inside the drawer
  let drawerContent = content;

  // If items array is provided, render them as BottomDrawerMenuItems
  if (items && items.length > 0) {
    drawerContent = (
      <BottomDrawerMenuItems>
        {items.map((item, index) => {
          const { label, ...itemProps } = item;
          return (
            <BottomDrawerMenuItem
              key={item.label}
              {...itemProps}
              isLast={itemProps.isLast ?? index === items.length - 1}
            >
              {label}
            </BottomDrawerMenuItem>
          );
        })}
      </BottomDrawerMenuItems>
    );
  }

  return (
    <BottomDrawer
      title={title}
      trigger={children}
      open={isOpen}
      onOpenChange={setIsOpen}
      classNames={{
        ...classNames,
        childrenWrapper: cn("px-0", classNames?.childrenWrapper),
      }}
    >
      <MenuProvider
        menuType="bottom-drawer"
        closeMenu={closeMenu}
        open={isOpen}
      >
        {drawerContent}
      </MenuProvider>
    </BottomDrawer>
  );
};

"use client";

import { createContext, useContext } from "react";

interface DrawerContextType {
  close: () => void;
}

export const DrawerContext = createContext<DrawerContextType | null>(null);

export const useDrawer = () => {
  const context = useContext(DrawerContext);
  if (!context) {
    throw new Error("useDrawer must be used within a DrawerProvider");
  }
  return context;
};

"use client";

import type { LucideIcon } from "lucide-react";
import Link from "next/link";
import React from "react";

import type { ReactFC } from "@/lib/types";
import { cn } from "@/lib/utils";
import { HelpInfoCircle } from "@/registry/new-york/help-info-circle/HelpInfoCircle";
import { MenuShortcut } from "@/registry/new-york/kbd-shortcuts/MenuShortcut";
import { useMenuContext } from "@/registry/new-york/menu-context/MenuContext";

export interface BottomDrawerMenuItemProps {
  children: React.ReactNode;
  leftIcon?: LucideIcon | undefined;
  rightIcon?: LucideIcon | undefined;
  emoji?: string | undefined;
  className?: string | undefined;
  disabled?: boolean | undefined;
  destructive?: boolean | undefined;
  onClick?: ((event: React.MouseEvent<HTMLElement>) => void) | undefined;
  onBlur?: (() => void) | undefined;
  textClassName?: string | undefined;
  leftIconClassName?: string | undefined;
  rightIconClassName?: string | undefined;
  shortcutClassName?: string | undefined;
  hintClassName?: string | undefined;
  href?: string | undefined;
  external?: boolean | undefined;
  isLast?: boolean | undefined;
  shortcut?: string | string[] | undefined;
  hint?: string | undefined;
  closeOnClick?: boolean | undefined;
}
export const BottomDrawerMenuItem: ReactFC<BottomDrawerMenuItemProps> = ({
  children,
  leftIcon: LeftIcon,
  rightIcon: RightIcon,
  emoji,
  className,
  disabled,
  destructive,
  onClick,
  onBlur,
  textClassName,
  leftIconClassName,
  rightIconClassName,
  shortcutClassName,
  hintClassName,
  href,
  external,
  isLast,
  shortcut,
  hint,
  closeOnClick = true,
}) => {
  const { closeMenu } = useMenuContext();
  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    if (disabled) {
      event.preventDefault();
      return;
    }
    onClick?.(event);
    if (closeOnClick && !event.defaultPrevented) {
      closeMenu?.();
    }
  };
  const iconClasses = cn(
    "h-5 w-5",
    "text-muted-foreground",
    destructive && "text-current"
  );
  const itemClasses = cn(
    "flex w-full min-w-0 cursor-pointer items-center gap-3 px-4 py-3 text-base",
    "transition-colors active:bg-zinc-50 dark:active:bg-zinc-800/50",
    "focus-visible:outline-ring justify-start text-left focus-visible:outline-2 focus-visible:outline-offset-[-2px]",
    disabled && "pointer-events-none opacity-50",
    destructive && "text-red-600 dark:text-red-400",
    !isLast &&
      "border-zinc-100 dark:border-zinc-800 [&:has(+[data-slot=bottom-drawer-menu-item])]:border-b",
    className
  );
  const content = (
    <>
      {emoji ? (
        <span className="inline-flex size-5 shrink-0 items-center justify-center text-base">
          {emoji}
        </span>
      ) : (
        LeftIcon && (
          <LeftIcon
            className={cn("shrink-0", iconClasses, leftIconClassName)}
          />
        )
      )}
      <span className={cn("min-w-0 flex-1", textClassName)}>{children}</span>
      {hint && (
        <span
          className={cn("inline-flex shrink-0 items-center", hintClassName)}
        >
          <HelpInfoCircle
            content={hint}
            drawerTitle="Help"
            iconClassName={destructive ? "text-current" : ""}
          />
        </span>
      )}
      {RightIcon && (
        <RightIcon
          className={cn("shrink-0", iconClasses, rightIconClassName)}
        />
      )}
      {shortcut && (
        <MenuShortcut
          shortcut={shortcut}
          destructive={destructive}
          className={shortcutClassName}
        />
      )}
    </>
  );
  if (href) {
    if (external) {
      return (
        <a
          data-slot="bottom-drawer-menu-item"
          onBlur={onBlur}
          aria-disabled={disabled || undefined}
          tabIndex={disabled ? -1 : undefined}
          className={itemClasses}
          href={href}
          onClick={handleClick}
          rel="noopener noreferrer"
          target="_blank"
        >
          {content}
        </a>
      );
    }
    return (
      <Link
        data-slot="bottom-drawer-menu-item"
        onBlur={onBlur}
        aria-disabled={disabled || undefined}
        tabIndex={disabled ? -1 : undefined}
        className={itemClasses}
        href={href}
        onClick={handleClick}
      >
        {content}
      </Link>
    );
  }
  return (
    <button
      type="button"
      data-slot="bottom-drawer-menu-item"
      onBlur={onBlur}
      className={itemClasses}
      disabled={disabled}
      onClick={handleClick}
    >
      {content}
    </button>
  );
};

import React from "react";

import type { ReactFC } from "@/lib/types";
import { cn } from "@/lib/utils";

// Label
export interface BottomDrawerMenuLabelProps {
  children: React.ReactNode;
  className?: string | undefined;
}

export const BottomDrawerMenuLabel: ReactFC<BottomDrawerMenuLabelProps> = ({
  children,
  className,
}) => (
  <div
    className={cn(
      "px-4 py-2 text-left text-sm font-medium text-zinc-500 dark:text-zinc-400",
      className
    )}
  >
    {children}
  </div>
);

// Separator
export interface BottomDrawerMenuSeparatorProps {
  className?: string | undefined;
}

export const BottomDrawerMenuSeparator: ReactFC<
  BottomDrawerMenuSeparatorProps
> = ({ className }) => (
  <hr
    data-slot="bottom-drawer-menu-separator"
    className={cn(
      "my-1 h-px w-full shrink-0 border-0 bg-zinc-100 dark:bg-zinc-800",
      className
    )}
  />
);

// Group
export interface BottomDrawerMenuGroupProps {
  children: React.ReactNode;
  className?: string | undefined;
}

export const BottomDrawerMenuGroup: ReactFC<BottomDrawerMenuGroupProps> = ({
  children,
  className,
}) => <div className={cn("flex w-full flex-col", className)}>{children}</div>;

// Consecutive items provide their own separators.
export interface BottomDrawerMenuItemsProps {
  children: React.ReactNode;
  className?: string | undefined;
}

export const BottomDrawerMenuItems: ReactFC<BottomDrawerMenuItemsProps> = ({
  children,
  className,
}) => <div className={cn("flex flex-col", className)}>{children}</div>;

// Group with title and items
export interface BottomDrawerGroupProps {
  title?: string | undefined;
  children: React.ReactNode;
  className?: string | undefined;
  titleClassName?: string | undefined;
}

export const BottomDrawerGroup: ReactFC<BottomDrawerGroupProps> = ({
  title,
  children,
  className,
  titleClassName,
}) => (
  <div className={cn("flex w-full flex-col", className)}>
    {title && (
      <BottomDrawerMenuLabel className={titleClassName}>
        {title}
      </BottomDrawerMenuLabel>
    )}
    <BottomDrawerMenuItems>{children}</BottomDrawerMenuItems>
  </div>
);

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
